#include <bits/stdc++.h>
using namespace std;
#define int long long
#define endl '\n'
void solve(){
    int n;
    cin>>n;
    vector<int> a(n);
    multiset<int> mt;
    for(int i = 0 ; i < n ; i++){
        cin>>a[i];
    }
    vector<int> arr;
    for(int i = 0 ; i < n ; i++){
        arr.push_back(a[i]);
    }
    for(int i = 0 ; i < n ; i++){
        arr.push_back(a[i]);
    }
    int ans = INT_MAX;
    for(int i = 0 ; i < 2*n - 1 ; i++){
        mt.insert(abs(arr[i+1] - arr[i]));
        ans = min(ans,*mt.begin());
        if(i >= n-1){
            mt.erase(mt.find(abs(arr[i-(n-1) + 1] - arr[i-(n-1)])));
        }
    }
    cout<<ans<<endl;
}
signed main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
	int t;
	cin>>t;
	while(t--){
	    solve();
	}

}
